CREATE   VIEW dbo.vw_monthly_regional_category_performance  AS  select   datefromparts(year(order_date),  month(order_date) ,  1 ) as order_month,region,category,  sum(sales) as total_sales,  sum(profit) as total_profit ,  round(  sum(profit)/nullif(sum(sales),0)*100.0,2) as profit_margin,  sum(quantity) as total_quantity,  count(distinct order_id) as distinct_orders,  count(distinct customer_id ) as distinct_customers,  count(case  when discount>0 then 1   end) as discounted_rows,  count(*) as total_rows,  round(avg(discount)*100.0,2) as average_discount_ptc,  round(max(discount)*100.0,2) as max_discount_ptc  from dbo.clean_superstore_orders  group by datefromparts(year(order_date),month(order_date),1) ,  region,category;  